update public.sentences set tokens = '[{"form_ids":["c6dc5176-6a91-5309-b0d1-e3d53a5d569d"],"surface":"Lograr","gloss":"getting"},{"form_ids":["6f175c15-d6f9-5a44-9fbf-8f177e533ee8"],"surface":"ese","gloss":"that"},{"form_ids":["147dfcbc-8f82-5616-98f2-43a271b78564"],"surface":"acento","gloss":"accent"},{"form_ids":["1ed2393d-a340-50b3-8c63-de2c49b7d78e"],"surface":"en","gloss":"in"},{"form_ids":["060197a5-9154-5a14-ac6d-8a8ffa3e9f6b"],"surface":"un","gloss":"a year"},{"form_ids":["e49c942a-1ba5-565e-bfef-ce762826db42"],"surface":"año","gloss":"a year"},{"form_ids":["b20bba62-c9b9-5803-9cdf-93d9b550a550"],"surface":"es","gloss":"is"},{"form_ids":["228ba1d7-ec0d-5278-970f-f36d9fd9bdb1"],"surface":"increíble.","gloss":"incredible"}]'::jsonb, en = 'Getting that accent in a year is incredible.', en_alt = array['Achieving that accent in one year is amazing.','Getting that accent down in a year is incredible.']::text[] where id = 'c662b63c-aad4-5c6a-bee2-5974317eceb4' and updated_at = '2026-09-27 09:50:21.28704+00';
update public.tips set body_md = '**Facturas** are the pastries you buy by the dozen at the bakery — *medialunas* are the best known. The same word also means *invoice*, but at the bakery it''s always pastries.' where id = '7d00df14-5cdf-59b1-9f3d-dc74b8626908' and body_md = '**Facturas** are the pastries you buy by the dozen at the bakery — *medialunas* are the best known. Nothing to do with bills.';
update public.tips set body_md = 'To say who you are, use **soy**: *Soy Sofi.* One word carries "I am" . The word for "I" (**yo**) is usually left out; add it only to stress or contrast: *Yo soy Martín.*' where id = '03c07d66-92a9-54f3-842f-c123a1a62c76' and body_md = 'To say who you are, use **soy**: *Soy Sofi.* One word carries "I am" — Spanish has no separate word for "I" here.';
update public.tips set body_md = '**Che** is how people in Buenos Aires get someone''s attention — like "hey": *Che, ¿todo bien?* It can also close a greeting: *Hola, che.* It''s friendly and casual — not for formal moments.' where id = '8b938cde-ecea-5e1b-bd22-3219656dc110' and body_md = '**Che** is how people in Buenos Aires get someone''s attention — like "hey": *Che, ¿todo bien?* It can also close a greeting: *Hola, che.* It''s friendly, never rude.';
update public.tips set body_md = '*Ser* says who you are — a name, or a role with no *un* in front:

| yo | **soy** | Soy estudiante. |
| vos | **sos** | ¿Sos turista? |


*Vos* can go before the verb or after it: *¿Vos sos Juan?* and *¿Sos vos?* are both everyday Buenos Aires.' where id = 'ff11688b-78a3-534f-8c4a-32fef8de8cd2' and body_md = '*Ser* says who you are — a name, or a role with no *un* in front:

| yo | **soy** | Soy estudiante. |
| vos | **sos** | ¿Sos turista? |
| vos | **sos vos** | ¿Sos vos? — Sí, soy yo. |

*Vos* can go before the verb or after it: *¿Vos sos Juan?* and *¿Sos vos?* are both everyday Buenos Aires.';
update public.tips set body_md = '*Ser de* works for a country, a city or one corner of it: **Soy de un pueblo de Córdoba.** **Soy de zona sur.** *Zona norte*, *zona sur* and *zona oeste* go straight after *de* — no *la*.' where id = '365922d8-9f57-5d59-8640-f9a66dff0181' and body_md = '*Ser de* works for a country, a city or one corner of it: **Soy de un pueblo de Córdoba.** **Soy de zona sur.** *Zona norte*, *zona sur* and *zona oeste* take no extra word.';
update public.tips set body_md = 'Someone from the city of Buenos Aires is **porteño** or **porteña** — from *puerto*, the port. People from the suburbs or the rest of the country are not.' where id = '5ee9b5a6-665f-5a3d-95f7-59b3e29898c9' and body_md = 'Someone from the city of Buenos Aires is **porteño** or **porteña** — from *puerto*, the port. People from the rest of the country are not.';
update public.tips set body_md = '**Mi viejo** and **mi vieja** — literally "my old one" — are affectionate Argentine words for *my dad* and *my mom*. Together: **mis viejos** — *my parents*.' where id = 'f64b190f-60eb-5b5b-8017-03d0b27f48d1' and body_md = '**Mi viejo** and **mi vieja** — literally "my old one" — are affectionate Argentine words for *my dad* and *my mom*.';
update public.tips set body_md = 'Words for people follow the person: *mi tío, mi tía*; *brasileño, brasileña*. A word in *-e* stays put: *canadiense*. One ending in a consonant adds *-a*: *francés → francesa*.' where id = 'd244b49a-e1eb-5cb3-9ae8-b0efee8aa45d' and body_md = 'Words for people follow the person: *mi tío, mi tía*; *brasileño, brasileña*. A word in *-e* stays put: *canadiense*.';
update public.tips set body_md = 'The word for "the" matches its noun: **el** kiosco, **la** empanada, **los** kioscos, **las** empanadas.' where id = 'e70098bf-8ca4-58e1-95ea-97fbd9aba81f' and body_md = 'The word for "the" matches its noun: **el** kiosco, **la** esquina, **los** kioscos, **las** esquinas.';
update public.tips set body_md = '| yo | **estoy** |
| vos | **estás** |
| él, ella | **está** |

Two verbs mean *to be*. **Ser** says who or what something is, and where it''s from: *Soy de Rosario.* **Estar** says where it is right now: *Estoy en Buenos Aires.*' where id = '2aa3d8f0-61b1-5ee4-b749-7d81ee01ea5c' and body_md = '| yo | **estoy** |
| vos | **estás** |
| él, ella | **está** |

Two verbs mean *to be*. **Ser** says who or what something is, and where it''s from: *Soy de Rosario.* **Estar** says where it is right now: *Estoy en el centro.*';
update public.tips set body_md = '*Estar* for where things are, one or several:

| one thing | **¿Dónde está** mi celu? | **Está** en la mochila. |
| several | **¿Dónde están** mis llaves? | **Están** en casa. |

 ' where id = 'f82557ff-141e-54a4-ae53-24b9b3574cee' and body_md = '*Estar* for where things are, one or several:

| one thing | **¿Dónde está** mi celu? | **Está** en la mochila. |
| several | **¿Dónde están** mis llaves? | **Están** en casa. |

No *la* before home: **en casa**. *Arriba, abajo, adentro* need nothing after them: *Estoy abajo.*';
update public.tips set body_md = '| something new | something you already know |
| **Hay** un kiosco. | **El** kiosco **está** en la esquina. |
| **Hay** una parada acá. | **La** parada **está** lejos. |
**Hay** goes with *un, una*, a number or no little word at all, and never changes: *hay dos kioscos*, *¿hay agua?* **Está** goes with *el, la*.' where id = 'ec69da9b-919b-5227-808d-abb58a8beed8' and body_md = '| something new | something you already know |
| **Hay** un kiosco. | **El** kiosco **está** en la esquina. |
| **Hay** una parada acá. | **La** parada **está** lejos. |
**Hay** goes with *un, una*, a number or no little word at all, and never changes: *hay dos subtes*, *¿hay agua?* **Está** goes with *el, la*.';
update public.tips set body_md = '| asking | **¿Hay** una estación **por acá**? |
| yes | Sí, **hay** una en la avenida. |
| no | No, acá no **hay** tren. |
| where | La estación **está** a dos cuadras. |

**Hay** never changes: *hay un bar*, *hay dos plazas*, *hay gente*. ' where id = 'c41cf955-fb7f-5670-b1e2-cc4a2a59f30c' and body_md = '| asking | **¿Hay** una estación **por acá**? |
| yes | Sí, **hay** una en la avenida. |
| no | No, acá no **hay** tren. |
| where | La estación **está** a dos cuadras. |

**Hay** never changes: *hay un bar*, *hay dos plazas*, *hay gente*. And *a + el* is still **al**, *de + el* is **del**: *al parque*, *la estación del subte*.';
update public.tips set body_md = '| yo | estoy | vos | estás |
| él, ella | está | nosotros | **estamos** |
| ellos, ustedes | **están** | | |

The word for the feeling matches the people in number too:

| one man | cansad**o** | one woman | cansad**a** |
| men | cansad**os** | women | cansad**as** |

A word ending in *-e* just adds *-s*: *triste, tristes*. *Feliz* becomes **felices**. **¿Sos feliz?**, with *ser*, asks about your life in general, not just right now.' where id = '5efb235d-d57c-58e4-8155-fd6c834d0300' and body_md = '| yo | estoy | vos | estás |
| él, ella | está | nosotros | **estamos** |
| ellos, ustedes | **están** | | |

The word for the feeling matches the people in number too:

| one man | cansad**o** | one woman | cansad**a** |
| men | cansad**os** | women | cansad**as** |

A word ending in *-e* just adds *-s*: *triste, tristes*. *Feliz* becomes **felices**.';
update public.tips set body_md = 'Porteños say **a la noche** for *at night* or *tonight*: *A la noche estudio inglés.* *Hablamos a la noche* — we''ll talk tonight. **De noche** is at night in general: *laburo de noche*. And **¿qué hacés?** — literally *what are you doing?* — is also the everyday *how''s it going?*: *Hola, ¿qué hacés?*' where id = '9b8de7a7-8ce6-5500-a8ab-a7d35c9c940e' and body_md = 'Porteños say **a la noche** for *at night*: *A la noche estudio inglés.* And **¿qué hacés?** — literally *what are you doing?* — is also the everyday *how''s it going?*: *Hola, ¿qué hacés?*';
update public.tips set body_md = '**Buscar** is *to look for* — no *for* needed: *busco una palabra*. **Preguntar** is *to ask* a question: *pregunto dónde está la parada*. With a person, though, put **a** in front: *extraño a mi familia*, *ayudamos a mis abuelos*. Only for a specific person: *busco a Sofi*, but *busco una profe*.' where id = 'c2a5f3ac-9d60-5f16-b276-32fe3605b2f1' and body_md = '**Buscar** is *to look for* — no *for* needed: *busco una palabra*. **Preguntar** is *to ask* a question: *pregunto por qué*. With a person, though, put **a** in front: *extraño a mi familia*, *ayudamos a mis abuelos*.';
update public.tips set body_md = 'The verb matches the thing you like, not you:
| one thing | more than one |
| Me **gusta** el mate. | Me **gustan** las facturas. |
| ¿Te **gusta** la milanesa? | ¿Te **gustan** los mates? |
**Me** — to me, **te** — to you, **le** — to him or her. For emphasis, add *a mí*: *A mí me gusta amargo.* With a name you need **a** and **le**: *A Lucía le gusta el mate.* Short answers: *A mí sí. A mí no.* With a verb it''s always *gusta*: *me gusta tomar mate*.' where id = '1861263d-ed73-5540-a7c8-6bd95804c94e' and body_md = 'The verb matches the thing you like, not you:
| one thing | more than one |
| Me **gusta** el mate. | Me **gustan** las facturas. |
| ¿Te **gusta** la milanesa? | ¿Te **gustan** los mates? |
**Me** — to me, **te** — to you, **le** — to him or her. For emphasis, add *a mí*: *A mí me gusta amargo.* With a verb it''s always *gusta*: *me gusta tomar mate*.';
update public.tips set body_md = '*Estar* and the describing word after it match the person: *estamos cansad**os***. An -ar verb takes the person''s ending: *practic**amos***. *Gustar* matches the thing: *nos gust**an** los fideos*.' where id = '1f297d17-80f0-51a1-b06f-6a3cab920a9b' and body_md = '*Estar* and its word match the person: *estamos cansad**os***. An -ar verb takes the person''s ending: *practic**amos***. *Gustar* matches the thing: *nos gust**an** los fideos*.';
update public.tips set body_md = 'In Argentina the waiter is **el mozo** (or *la moza*). To call one over, *perdón* is the gentle way; *¡mozo!* is heard too. When you''re done, ask for **la cuenta**. A **cortado** is an espresso with a dash of milk.' where id = '5accb3e5-9f5d-571b-b159-856ad4feb161' and body_md = 'In Argentina the waiter is **el mozo** (or *la moza*). When you''re done, ask for **la cuenta**. A **cortado** is an espresso with a dash of milk.';
update public.tips set body_md = '**Soda** is fizzy water, still served from a siphon in the old cafés. It is not a soft drink — that is **gaseosa**. On a menu you will see **agua con gas** (sparkling) and **agua sin gas** (still). A **picada** is a board of cheese and cold cuts to share before dinner.' where id = '899d348a-60ee-5d03-bc6d-af23743c92be' and body_md = '**Soda** is fizzy water, still served from a siphon in the old cafés. A **picada** is a board of cheese and cold cuts to share before dinner.';
update public.tips set body_md = '**Tener que** + an infinitive — the *-ar, -er, -ir* form — is *to have to*:

| Tengo que laburar. | I have to work. |
| ¿Tenés que estudiar? | Do you have to study? |

Jobs change for a woman: *profesor* → **profesora**, *médico* → **médica**, *jefe* → **jefa**. And no *un, una*: **Soy abogada.** **Que** also joins two ideas: *tengo una jefa que habla inglés* — a boss who speaks English.' where id = 'ae41a407-af9b-5cde-9ad6-f0b967fd6c3a' and body_md = '**Tener que** + an infinitive — the *-ar, -er, -ir* form — is *to have to*:

| Tengo que laburar. | I have to work. |
| ¿Tenés que estudiar? | Do you have to study? |

Jobs change for a woman: *profesor* → **profesora**, *médico* → **médica**, *jefe* → **jefa**. And no *un, una*: **Soy abogada.**';
update public.tips set body_md = '*Tener que* works with every person: *tenemos que laburar*, *los médicos tienen que ayudar*. **Buscar** also means *to pick someone up*: *tengo que buscar a mi hijo*.' where id = '3910aabd-7879-56ce-9fd0-298db2aac86c' and body_md = '*Tener que* works with every person: *tenemos que laburar*, *los médicos tienen que ayudar*. After it, **buscar** is also *to pick someone up*: *tengo que buscar a mi hijo*.';
update public.tips set body_md = '| | leer | compartir | escribir |
| yo | le**o** | compart**o** | escrib**o** |
| vos | le**és** | compart**ís** | escrib**ís** |
| él, ella | le**e** | compart**e** | escrib**e** |
| nosotros | le**emos** | compart**imos** | escrib**imos** |
| ellos, ustedes | le**en** | compart**en** | escrib**en** |

-er keeps **e** and -ir takes **i**, but only for *vos* and *nosotros*: *vend**és**, vend**emos*** but *abr**ís**, abr**imos***. *Recibir* and *correr* follow the same pattern: *recibo, recibís, recibe*.' where id = 'ff18c38c-372c-591e-a3e1-3ae0c2d65dfc' and body_md = '| | leer | compartir | escribir |
| yo | le**o** | compart**o** | escrib**o** |
| vos | le**és** | compart**ís** | escrib**ís** |
| él, ella | le**e** | compart**e** | escrib**e** |
| nosotros | le**emos** | compart**imos** | escrib**imos** |
| ellos, ustedes | le**en** | compart**en** | escrib**en** |

-er keeps **e** and -ir takes **i**, but only for *vos* and *nosotros*: *vend**és**, vend**emos*** but *abr**ís***. *Recibir* and *correr* follow the same pattern: *recibo, recibís, recibe*.';
update public.tips set body_md = '*Es la una* (one o''clock), but *son las dos*, *son las siete*. Add **y media** for half past and **y cuarto** for quarter past. *At* a time is **a las**: *¿A qué hora?* — *A las nueve y media.* After a clock time say **de la mañana / de la tarde / de la noche**: *a las dos de la tarde*. With no clock time: **a la mañana**, *a la tarde*, *a la noche*.' where id = '97b6abce-e595-58cb-a895-30319da57ada' and body_md = '*Es la una* (one o''clock), but *son las dos*, *son las siete*. Add **y media** for half past and **y cuarto** for quarter past. *At* a time is **a las**: *¿A qué hora?* — *A las nueve y media.*';
update public.tips set body_md = 'Opening hours are **desde** … **hasta**: *abre desde las nueve hasta las seis*. Shorter, and more common: *abre **de** nueve **a** seis*. At twelve it''s **el mediodía** — and plenty of small shops **cierran** for a while right after it.' where id = '7782b8c8-3797-5039-896a-6aeac6b65951' and body_md = 'Opening hours are **desde** … **hasta**: *abre desde las nueve hasta las seis*. At twelve it''s **el mediodía** — and plenty of small shops **cierran** for a while right after it.';
update public.tips set body_md = '**al lado de** (next to), **enfrente de** (across from), **atrás de** (behind), **adelante de** (in front of), **entre** (between). Careful: *enfrente* is across the street, not *in front*. Remember *de + el* = *del*: *al lado del kiosco*. With no place after them, drop the *de*: *está enfrente*, *vivo al lado*.' where id = 'e9b5fcfc-ba53-5a53-b7c5-cfbebadbf0e4' and body_md = '**al lado de** (next to), **enfrente de** (across from), **atrás de** (behind), **entre** (between). Remember *de + el* = *del*: *al lado del kiosco*. With no place after them, drop the *de*: *está enfrente*, *vivo al lado*.';
update public.tips set body_md = 'Left and right both take **a la**: **a la derecha**, **a la izquierda**. To say what something is left or right of, add **de**: *la farmacia está a la derecha del banco*.' where id = 'a3090b0a-0804-5173-a69d-b576f39b56f7' and body_md = 'Left and right both take **a la**: **a la derecha**, **a la izquierda**. Put them after the place: *la farmacia está a la derecha del banco*.';
update public.tips set body_md = '| | querer | poder | ir |
| yo | quiero | puedo | voy |
| vos | **querés** | **podés** | vas |
| él, ella | quiere | puede | va |
| nosotros | **queremos** | **podemos** | vamos |
| ellos | quieren | pueden | van |
*e → ie* and *o → ue* everywhere except **vos** and **nosotros**. *Ir* is its own thing, and takes **a** + place (*a + el* = **al**): *voy al súper*, *voy a la facu*. **Salir** only bends in *yo*: **salgo**, *salís*, *sale*. Add an infinitive for plans: *¿Querés salir?*' where id = '78286e2b-e254-5636-a5a8-883bdf68f891' and body_md = '| | querer | poder | ir |
| yo | quiero | puedo | voy |
| vos | **querés** | **podés** | vas |
| él, ella | quiere | puede | va |
| nosotros | **queremos** | **podemos** | vamos |
| ellos | quieren | pueden | van |
*e → ie* and *o → ue* everywhere except **vos** and **nosotros**. *Ir* is its own thing: *voy al súper*, *voy a la facu*. **Salir** only bends in *yo*: **salgo**, *salís*, *sale*. Add an infinitive for plans: *¿Querés salir?*';
update public.tips set body_md = 'More verbs that stretch their stem — but never with vos:
| | preferir | volver | empezar |
| yo | pref**ie**ro | v**ue**lvo | emp**ie**zo |
| vos | **preferís** | **volvés** | **empezás** |
| él, ella | pref**ie**re | v**ue**lve | emp**ie**za |
| ellos | pref**ie**ren | v**ue**lven | emp**ie**zan |
The same as *quiero, querés* and *puedo, podés*. **Nosotros** stays short too: *preferimos, volvemos, empezamos*. Add an infinitive for the plan: *¿Preferís ir al teatro?*' where id = '4dbef0fb-6aa3-5103-be47-ebffcb6a29cd' and body_md = 'More verbs that stretch their stem — but never with vos:
| | preferir | volver | empezar |
| yo | pref**ie**ro | v**ue**lvo | emp**ie**zo |
| vos | **preferís** | **volvés** | **empezás** |
| él, ella | pref**ie**re | v**ue**lve | emp**ie**za |
| ellos | pref**ie**ren | v**ue**lven | emp**ie**zan |
The same as *quiero, querés* and *puedo, podés*. Add an infinitive for the plan: *¿Preferís ir al teatro?*';
update public.tips set body_md = 'Take the infinitive, drop the *-r*, and stress the last vowel:

| mirar | **mirá** |
| esperar | **esperá** |
| venir | **vení** |
| andar | **andá** |

A pronoun joins the end, and the accent goes, because the stress doesn''t move: *esperá* → **esperame**. *Decir* → **decime**, *sentarse* → **sentate**. To tell someone to *go*, use **andá** — *ir* has no vos command of its own: *andá al médico*.' where id = 'cf20bac1-fd65-59f0-834e-7f80f5a732a5' and body_md = 'Take the infinitive, drop the *-r*, and stress the last vowel:

| mirar | **mirá** |
| esperar | **esperá** |
| venir | **vení** |
| andar | **andá** |

A pronoun joins the end, and the accent goes, because the stress doesn''t move: *esperá* → **esperame**. *Decir* → **decime**, *sentarse* → **sentate**.';
update public.tips set body_md = 'Adjectives match their noun: *remera linda*, *zapatillas lindas*. Ones ending in *-e* or a consonant only change for more than one: *verde* → **verdes**, *azul* → **azules**. **Re** in front of an adjective means *really*: *re lindo*. **Muy** is *very* — and *muy chica para Juan* is *too small for Juan*. And **chico** means *small* — and also *boy* or *girl*: *la chica de la remera verde* is *the girl in the green T-shirt*.' where id = '14ab3922-a0da-5828-9009-788ce80ae5c3' and body_md = 'Adjectives match their noun: *remera linda*, *zapatillas lindas*. Ones ending in *-e* or a consonant only change for more than one: *verde* → **verdes**, *azul* → **azules**. **Re** in front of an adjective means *really*: *re lindo*. And **chico** means *small*.';
update public.tips set body_md = '*Amarillo* works like *rojo*: **amarilla, amarillos**. But **gris** and **marrón** are the same for *el* and *la* — *un buzo gris*, *una campera gris* — and only add *-es* for more than one: *unas zapatillas grises*.' where id = '790b188b-f364-5b46-be9e-6e1fe3996e4a' and body_md = '*Amarillo* works like *rojo*: **amarilla, amarillos**. But **gris** and **marrón** only add *-es* for more than one: *un buzo gris*, *unas zapatillas grises*.';
update public.tips set body_md = 'Your clothing size is your **talle**: *¿Qué talle usás?* (you''ll also hear *¿Qué talle sos?*) Argentine sizes run small, so ask to try it on before you pay.' where id = '834d42dc-2aa8-5ffa-b50d-ecbf01e319e5' and body_md = 'Your clothing size is your **talle**: *¿Qué talle sos?* Argentine sizes run small, so ask to try it on before you pay.';
update public.tips set body_md = '**¿Cuánto sale?** is the everyday Argentine way to ask a price — *¿cuánto cuesta?* works too. One thing **cuesta**, several **cuestan**: *las zapatillas cuestan doscientos mil*. Same with *sale*: several things **salen** — *¿cuánto salen las zapatillas?* **Mangos** is slang for pesos.' where id = 'fe95866f-3747-5f76-84e6-70b1453b221c' and body_md = '**¿Cuánto sale?** is the everyday Argentine way to ask a price — *¿cuánto cuesta?* works too. One thing **cuesta**, several **cuestan**: *las zapatillas cuestan doscientos mil*. **Mangos** is slang for pesos.';
update public.tips set body_md = 'The vos command is everywhere in a shop: **mirá**, **fijate**, **esperame**, **tomá** — *tomá, tu vuelto*. Drop the *-r* and stress the last vowel of the verb: *mirá*, *tomá*. With *me* or *te* added, the stress stays there: *fijate* (fi-JA-te), *esperame* (es-pe-RA-me).' where id = 'a9c6a548-7adb-5fe2-ab0e-9c5cc53eefa8' and body_md = 'The vos command is everywhere in a shop: **mirá**, **fijate**, **esperame**, **tomá** — *tomá, tu vuelto*. Drop the *-r*, stress the end.';
update public.tips set body_md = 'These verbs carry a pronoun that matches the person:
| yo | **me** levanto | **me** acuesto |
| vos | **te** levantás | **te** acostás |
| él, ella | **se** levanta | **se** acuesta |
| nosotros | **nos** levantamos | |
The pronoun goes before the verb. *Acostarse* and *almorzar* change *o → ue*, but not with vos: **me acuesto**, **almuerzo** — **te acostás**, **almorzás**. **Los sábados** means *on Saturdays*; **antes de** + a verb is *before*: *antes de ir a la facu*. **Una vez por semana** is *once a week*; **a veces** is *sometimes*.' where id = '8eaa2931-6ddd-51a7-b8ae-6270f3bc71e8' and body_md = 'These verbs carry a pronoun that matches the person:
| yo | **me** levanto | **me** acuesto |
| vos | **te** levantás | **te** acostás |
| él, ella | **se** levanta | **se** acuesta |
| nosotros | **nos** levantamos | |
The pronoun goes before the verb. *Acostarse* changes *o → ue*, but not with vos: **te acostás**. **Los sábados** means *on Saturdays*; **antes de** + a verb is *before*: *antes de ir a la facu*.';
update public.tips set body_md = 'With a verb, *gusta* stays singular, even for two activities:
| Me gusta bailar. | Me gusta leer y cocinar. |
| Me encanta el fútbol. | Me encantan las series. |
Agreeing with *me gusta* or *me encanta*: **A mí también** after a *yes*, **A mí tampoco** after a *no*. With a normal verb it''s **yo**: *No bailo.* — *Yo tampoco.* **Jugar** stretches like *poder*: **juego**, but **jugás**.' where id = 'f255cb1b-020c-5d3c-bf67-3a14a5b0ebe8' and body_md = 'With a verb, *gusta* stays singular, even for two activities:
| Me gusta bailar. | Me gusta leer y cocinar. |
| Me encanta el fútbol. | Me encantan las series. |
Agreeing: **A mí también** after a *yes*, **A mí tampoco** after a *no*. **Jugar** stretches like *poder*: **juego**, but **jugás**.';
update public.tips set body_md = 'The thing liked is the subject; the pronoun says who likes it:
| a mí | **me** gusta nadar | **me** interesa el tenis |
| a vos | **te** gusta viajar | **te** interesan los deportes |
| a él, a ella | **le** gusta cantar | **le** interesa la música |
| a nosotros | **nos** gusta pasear | **nos** encanta la playa |
| a ellos | **les** gusta el fútbol | **les** encantan las series |
With a verb it stays singular: *me gusta nadar y cantar*. To name the person, put **a** in front and keep **le**: *A mi hermano le gusta nadar.* **Odiar** is a normal verb: *odio, odiás*.' where id = '66c19e01-5dde-5df7-b8e7-53568768b420' and body_md = 'The thing liked is the subject; the pronoun says who likes it:
| a mí | **me** gusta nadar | **me** interesa el tenis |
| a vos | **te** gusta viajar | **te** interesan los deportes |
| a él, a ella | **le** gusta cantar | **le** interesa la música |
| a nosotros | **nos** gusta pasear | **nos** encanta la playa |
| a ellos | **les** gusta el fútbol | **les** encantan las series |
With a verb it stays singular: *me gusta nadar y cantar*. *A mi hermano le gusta nadar.* **Odiar** is a normal verb: *odio, odiás*.';
update public.tips set body_md = '**Hace calor**, **hace frío** — it''s hot, it''s cold. But **hay sol**, **hay viento**, **está nublado**, and **llueve** alone (for right now you''ll also hear *está lloviendo*). You yourself **tenés frío**. Seasons are flipped: *el verano* runs from late December to March.' where id = 'd48b1ff9-881c-5010-bbf2-fd3a16bc7729' and body_md = '**Hace calor**, **hace frío** — it''s hot, it''s cold. But **hay sol**, **hay viento**, **está nublado**, and **llueve** alone. You yourself **tenés frío**. Seasons are flipped: *el verano* runs from December to February.';
update public.tips set body_md = '**Ir a** + infinitive talks about plans: *Vamos a hacer un asado.* **La semana que viene** is *next week*. Same with days: *el viernes que viene*. **El próximo viernes** means the same.' where id = '54719e83-d9d7-5d73-98e3-8ba760627cc8' and body_md = '**Ir a** + infinitive talks about plans: *Vamos a hacer un asado.* **La semana que viene** is *next week*.';
